1	/**
2	 * Funções puras de autenticação e permissões.
3	 * Extraídas de useAuth.tsx e usePermissions.tsx para facilitar testes unitários.
4	 */
5	
6	import type { UserProfile } from './useAuth';
7	
8	// ─── Constantes ───────────────────────────────────────────────────────────────
9	
10	export const CACHE_KEY_PREFIX = 'userProfile_';
11	export const CACHE_EXPIRY_MS = 5 * 60 * 1000; // 5 minutos
12	export const MAX_RETRIES = 2;
13	export const REFRESH_EARLY_SECONDS = 180; // ~3 min antes de expirar
14	export const CHECK_INTERVAL_MS = 60_000; // checar a cada 1 min
15	export const DEFAULT_STORE_ID = 5; // Asa Sul como padrão
16	
17	// ─── Interfaces ───────────────────────────────────────────────────────────────
18	
19	export interface Permission {
20	  permission_name: string;
21	  permission_display_name: string;
22	  module: string;
23	}
24	
25	export interface UserRole {
26	  role_name: string;
27	  role_display_name: string;
28	}
29	
30	export interface CacheEntry {
31	  profile: UserProfile;
32	  timestamp: number;
33	}
34	
35	export interface StorageLike {
36	  getItem(key: string): string | null;
37	  setItem(key: string, value: string): void;
38	  removeItem(key: string): void;
39	}
40	
41	// ─── Cache de perfil ──────────────────────────────────────────────────────────
42	
43	export function getCachedProfile(
44	  userId: string,
45	  storage: StorageLike,
46	  now = Date.now()
47	): UserProfile | null {
48	  try {
49	    const cacheKey = CACHE_KEY_PREFIX + userId;
50	    const cached = storage.getItem(cacheKey);
51	    if (!cached) return null;
52	
53	    const { profile, timestamp } = JSON.parse(cached) as CacheEntry;
54	
55	    if (now - timestamp > CACHE_EXPIRY_MS) {
56	      storage.removeItem(cacheKey);
57	      return null;
58	    }
59	
60	    return profile;
61	  } catch {
62	    return null;
63	  }
64	}
65	
66	export function setCachedProfile(
67	  userId: string,
68	  profile: UserProfile,
69	  storage: StorageLike,
70	  now = Date.now()
71	): void {
72	  try {
73	    const cacheKey = CACHE_KEY_PREFIX + userId;
74	    const cacheData: CacheEntry = { profile, timestamp: now };
75	    storage.setItem(cacheKey, JSON.stringify(cacheData));
76	  } catch {
77	    // silently ignore storage errors
78	  }
79	}
80	
81	export function clearUserCache(
82	  storage: StorageLike,
83	  userId?: string
84	): void {
85	  try {
86	    if (userId) {
87	      storage.removeItem(CACHE_KEY_PREFIX + userId);
88	    } else {
89	      // Precisamos iterar sobre as chaves — assumimos que storage
90	      // tem chaves acessíveis (localStorage). Como StorageLike não
91	      // garante keys(), usamos abordagem de array fornecido.
92	      // Na prática, chamado pelo hook que tem acesso ao localStorage.
93	    }
94	  } catch {
95	    // silently ignore
96	  }
97	}
98	
99	export function clearAllProfileCaches(keys: string[], storage: StorageLike): void {
100	  try {
101	    keys.forEach((key) => {
102	      if (key.startsWith(CACHE_KEY_PREFIX)) {
103	        storage.removeItem(key);
104	      }
105	    });
106	  } catch {
107	    // silently ignore
108	  }
109	}
110	
111	// ─── Perfil padrão para novos usuários ────────────────────────────────────────
112	
113	export function buildDefaultProfile(
114	  userId: string,
115	  displayName: string,
116	  username: string
117	): {
118	  user_id: string;
119	  nome: string;
120	  username: string;
121	  ativo: boolean;
122	  approved: boolean;
123	  needs_approval: boolean;
124	  default_store_id: number;
125	  can_change_store: boolean;
126	} {
127	  return {
128	    user_id: userId,
129	    nome: displayName,
130	    username,
131	    ativo: true,
132	    approved: false,
133	    needs_approval: true,
134	    default_store_id: DEFAULT_STORE_ID,
135	    can_change_store: false, // SEGURANÇA: Novos usuários não podem alterar loja
136	  };
137	}
138	
139	// ─── Perfil fallback (quando tudo falha) ──────────────────────────────────────
140	
141	export function createFallbackProfile(userId: string): UserProfile {
142	  return {
143	    id: `fallback_${userId}`,
144	    user_id: userId,
145	    nome: 'Usuário',
146	    username: 'usuario',
147	    ativo: true,
148	    role_id: null,
149	    approved: true,
150	    needs_approval: false,
151	    default_store_id: DEFAULT_STORE_ID,
152	    can_change_store: false, // SEGURANÇA: Fallback não pode alterar loja
153	    created_at: new Date().toISOString(),
154	    updated_at: new Date().toISOString(),
155	  };
156	}
157	
158	// ─── Detecção de erros ────────────────────────────────────────────────────────
159	
160	export function isNetworkError(error: { message?: string; name?: string }): boolean {
161	  return !!(error.message?.includes('network') || error.name === 'FetchError');
162	}
163	
164	export function isDuplicateKeyError(error: { message?: string; code?: string }): boolean {
165	  return !!(error.message?.includes('duplicate key value') || error.code === '23505');
166	}
167	
168	export function shouldRetry(
169	  error: { message?: string; name?: string },
170	  retryCount: number,
171	  maxRetries = MAX_RETRIES
172	): boolean {
173	  return retryCount < maxRetries && isNetworkError(error);
174	}
175	
176	// ─── Lógica de aprovação ──────────────────────────────────────────────────────
177	
178	export function computeNeedsApproval(profile: UserProfile | null): boolean {
179	  if (!profile) return false;
180	  return profile.needs_approval && !profile.approved;
181	}
182	
183	// ─── Refresh de sessão ────────────────────────────────────────────────────────
184	
185	export function shouldRefreshSession(
186	  expiresAt: number,
187	  nowSec: number,
188	  earlySeconds = REFRESH_EARLY_SECONDS
189	): boolean {
190	  if (expiresAt <= 0) return false;
191	  const secsToExpire = expiresAt - nowSec;
192	  return secsToExpire <= earlySeconds;
193	}
194	
195	export function getSecondsToExpire(expiresAt: number, nowSec: number): number {
196	  return expiresAt - nowSec;
197	}
198	
199	// ─── Extração de nome/username do auth user ───────────────────────────────────
200	
201	export function extractDisplayName(
202	  fullName: string | null | undefined,
203	  email: string | null | undefined
204	): string {
205	  if (fullName) return fullName;
206	  if (email) return email.split('@')[0];
207	  return 'Usuário';
208	}
209	
210	export function extractUsername(
211	  email: string | null | undefined,
212	  userId: string
213	): string {
214	  if (email) return email.split('@')[0];
215	  return `user_${userId.substring(0, 8)}`;
216	}
217	
218	// ─── Lógica de permissões ─────────────────────────────────────────────────────
219	
220	const ADMIN_ALIASES = ['admin', 'administrador', 'administrator'];
221	
222	export function isAdminRole(roleName: string | null | undefined): boolean {
223	  if (!roleName) return false;
224	  return ADMIN_ALIASES.includes(roleName.toLowerCase());
225	}
226	
227	export function hasPermission(
228	  permissions: Permission[],
229	  permissionName: string
230	): boolean {
231	  return permissions.some((p) => p.permission_name === permissionName);
232	}
233	
234	export function hasAnyPermission(
235	  permissions: Permission[],
236	  permissionNames: string[]
237	): boolean {
238	  return permissionNames.some((name) => hasPermission(permissions, name));
239	}
240	
241	export function canAccessModule(
242	  permissions: Permission[],
243	  module: string,
244	  admin: boolean
245	): boolean {
246	  if (admin) return true;
247	  return permissions.some((p) => p.module === module);
248	}
249	
250	/**
251	 * Verifica se o usuário tem uma permissão específica OU é admin.
252	 * Padrão usado por todas as funções canView* no usePermissions.
253	 */
254	export function canViewWithAdminBypass(
255	  permissions: Permission[],
256	  permissionName: string,
257	  admin: boolean
258	): boolean {
259	  return hasPermission(permissions, permissionName) || admin;
260	}
261	
262	/**
263	 * Lógica especial de canViewProntaEntrega: tem permissão OR pode ver estoque OR admin.
264	 */
265	export function canViewProntaEntrega(
266	  permissions: Permission[],
267	  admin: boolean
268	): boolean {
269	  return (
270	    hasPermission(permissions, 'view_pronta_entrega') ||
271	    hasPermission(permissions, 'view_estoque') ||
272	    admin
273	  );
274	}
