22	/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
23	const METAS_BUTTON_VISIBLE_MS = 5_000;
24	
25	/** Card-chassi anônimo do estado de erro total (design.md §7). */
26	function TvErrorCard() {
27	  return (
28	    <section className="flex flex-col rounded-2xl border border-tv-border bg-tv-surface p-5">
29	      <div className="flex h-8 items-center justify-between">
30	        <span className="text-[28px] font-momma font-semibold text-tv-dim">—</span>
31	        <span className="inline-flex h-6 items-center rounded-full border border-tv-amber/40 bg-tv-raised px-3 text-[20px] font-momma font-medium text-tv-amber">
32	          sem conexão
33	        </span>
34	      </div>
35	      <span className="mt-4 font-tv-num text-[64px] font-bold leading-none text-tv-dim">—</span>
36	    </section>
37	  );
38	}
