40	/** Página raiz do painel TV. */
41	export default function TvDashboardPage() {
42	  const navigate = useNavigate();
43	  const data = useTvDashboardData();
44	  useTvRealtime();
45	  const now = useMinuteClock();
46	
47	  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
48	  // e suspende o cursor-none enquanto visível (design.md §8.4).
49	  const [controlsVisible, setControlsVisible] = useState(false);
50	  const hideTimer = useRef<number | null>(null);
51	  useEffect(() => {
52	    const onMove = () => {
53	      setControlsVisible(true);
54	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
55	      hideTimer.current = window.setTimeout(
56	        () => setControlsVisible(false),
57	        METAS_BUTTON_VISIBLE_MS,
58	      );
59	    };
60	    window.addEventListener('mousemove', onMove);
61	    return () => {
62	      window.removeEventListener('mousemove', onMove);
63	      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
64	    };
65	  }, []);
66	
67	  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
68	  if (data.isLoading) {
69	    return (
70	      <div className="fixed inset-0 flex select-none flex-col items-center justify-center gap-5 overflow-hidden bg-tv-bg font-momma antialiased">
71	        <span className="text-[40px] font-bold uppercase tracking-[0.3em] text-tv-gold">
72	          MOMMA
73	        </span>
74	        <span className="text-[24px] text-tv-mut">carregando painel…</span>
75	        <div className="flex gap-2 text-[24px] text-tv-dim" aria-hidden>
76	          <span className="tv-dot">·</span>
77	          <span className="tv-dot">·</span>
78	          <span className="tv-dot">·</span>
79	        </div>
80	      </div>
81	    );
82	  }
83	
84	  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);
85	
86	  return (
87	    <div
88	      className={`fixed inset-0 select-none overflow-hidden bg-tv-bg font-momma text-tv-text antialiased ${
89	        controlsVisible ? '' : 'cursor-none'
90	      }`}
91	      data-testid="tv-dashboard"
92	    >
93	      <div className="tv-pixel-shift h-full">
94	        <div className="tv-content-enter grid h-full grid-rows-[152px_1fr_248px] gap-6 px-8 py-6">
95	          {/* Linha 1 — hero */}
96	          <TvHero network={data.network} freshness={data.freshness} now={now} />
97	
98	          {/* Linha 2 — grid 3×2 de unidades (fábrica na posição 6) */}
99	          <div className="grid grid-cols-3 grid-rows-2 gap-6">
100	            {data.isError ? (
101	              <>
102	                {Array.from({ length: 6 }, (_, i) => (
103	                  <TvErrorCard key={i} />
104	                ))}
105	              </>
106	            ) : (
107	              <>
108	                {storeCards.map((store) => (
109	                  <TvStoreCard
110	                    key={store.lojaId}
111	                    store={store}
112	                    liveLevel={data.freshness.vendasLive.level}
113	                    now={now}
114	                  />
115	                ))}
116	                {data.factory && (
117	                  <TvFabricaCard
118	                    factory={data.factory}
119	                    freshness={data.freshness}
120	                    now={now}
121	                  />
122	                )}
123	              </>
124	            )}
125	          </div>
126	
127	          {/* Linha 3 — exceções (2fr) + top 5 produtos (1fr) */}
128	          <div className="grid grid-cols-[2fr_1fr] gap-6">
129	            <TvExceptions exceptions={data.exceptions} />
130	            <TvTopProducts products={data.topProducts} />
131	          </div>
132	        </div>
133	      </div>
134	
135	      {/* Botão fantasma de Metas (§8.4) */}
136	      <button
137	        type="button"
138	        onClick={() => navigate('/tv/metas')}
139	        data-mia-action="abrir-metas-painel-tv"
140	        className={`fixed bottom-6 right-8 flex h-11 items-center gap-2 rounded-full border border-tv-border bg-tv-raised/80 px-5 text-[20px] font-momma font-medium text-tv-dim transition-opacity duration-200 motion-reduce:transition-none ${
141	          controlsVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
142	        }`}
143	        aria-hidden={!controlsVisible}
144	        tabIndex={controlsVisible ? 0 : -1}
145	      >
146	        <Settings2 style={{ width: 22, height: 22 }} aria-hidden />
147	        Metas
148	      </button>
149	    </div>
150	  );
